import _study  # noqa: E402

DATE = "2026-10-18"
_study.DATE = DATE
_study.AUTH = f"KI-Entwurf (Claude) vom {DATE} auf Wunsch von Andi Neck; keine fachliche Prüfung erfolgt."
_study.AUTH_GSW = (f"KI-Entwurf (Claude) vom {DATE}; aus dem Hochdeutschen in Züridüütsch gefasst; "
                   "Mundart noch nicht muttersprachlich geprüft.")

TAGS = ["TAG-MATTHEW"]
CHAPTERS = {8: "TU-MAT-008-001-034", 9: "TU-MAT-009-001-038", 10: "TU-MAT-010-001-042", 11: "TU-MAT-011-001-030",
            12: "TU-MAT-012-001-050", 13: "TU-MAT-013-001-058", 14: "TU-MAT-014-001-036"}
_UNITS = sorted(p.stem for p in (D / "text-units").rglob("TU-MAT-*.json"))


def U(ch, v1, v2=None):
    """Kleinste vorhandene Texteinheit, die Kapitel ch, Verse v1–v2 ganz enthält; sonst die Kapiteleinheit."""
    v2 = v2 or v1
    if ch not in CHAPTERS:
        raise SystemExit(f"Mt {ch} gehört nicht zu diesem Werkzeug")
    best = None
    for uid in _UNITS:
        m = re.fullmatch(r"TU-MAT-(\d{3})-(\d{3})-(\d{3})", uid)
        if m and int(m[1]) == ch and int(m[2]) <= v1 and int(m[3]) >= v2:
            if best is None or int(m[3]) - int(m[2]) < best[0]:
                best = (int(m[3]) - int(m[2]), uid)
    return best[1] if best else CHAPTERS[ch]


# Bestehender Kontext, unverändert übernommen (write() schreibt dann nichts)
CONTEXT = json.loads((D / "contexts" / "CTX-MAT-READERS-0085.json").read_text(encoding="utf-8"))
