# Hintergrund: (id, Abschnitt, Stelle, Kontext, Konfidenz, Thema, Text, unsicher, Belege, Quellen, Fachwörter | Mundart)
BACKGROUND = [
 ("BG-MAT-2001", U(8, 5, 13), "MAT.8.5", GAL, "probable", "Ein Hauptmann in Kafarnaum",
  "Ein «Hauptmann» (ἑκατόνταρχος) befehligte eine Einheit von etwa hundert Soldaten, im römischen Heer meist rund achtzig. In Galiläa standen zur Zeit Jesu keine römischen Legionen; das Gebiet gehörte dem Landesfürsten Herodes Antipas, der eigene, nach römischem Vorbild gegliederte Truppen hatte. Josephus erwähnt sie im Krieg des Antipas gegen den Nabatäerkönig Aretas. In solchen Truppen dienten auch Nichtjuden. Dass der Hauptmann kein Jude ist, ergibt sich aus dem Zusammenhang ([[MAT.8.10-MAT.8.11]]); ein Jude hätte bei einem Nichtjuden ins Haus gehen können, aber manche hielten das für verunreinigend (vgl. [[ACT.10.28]]).",
  "Ob der Mann im Dienst des Antipas oder einer römischen Hilfstruppe stand, sagt der Text nicht. Wie streng die Scheu vor nichtjüdischen Häusern damals war, ist umstritten.",
  ["MAT.8.5-MAT.8.13", "LUK.7.1-LUK.7.10", "ACT.10.28"], ["Josephus, Jüdische Altertümer 18,109–115"],
  [("grc", "ἑκατόνταρχος", "Hauptmann, Befehlshaber über hundert"), ("grc", "παῖς", "Knabe; Diener")],
  "En Hauptme z Kafarnaum",
  "En «Hauptme» (ἑκατόνταρχος) hät e Iiheit vo öppe hundert Soldate befolle, im römische Heer meischtens öppe achtzg. I Galiläa sind zur Ziit vo Jesus kei römischi Legione gstande; s Gebiet hät em Landesfürscht Herodes Antipas ghört, wo eigeti, nach römischem Vorbild gliideret Truppe gha hät. De Josephus erwäänt si im Chrieg vom Antipas gäge de Nabatäerkönig Aretas. I settige Truppe händ au Nöd-Jude dienet. Dass de Hauptme kein Jud isch, gseht me us em Zämehang ([[MAT.8.10-MAT.8.11]]); en Jud hett bi me Nöd-Jud is Huus chöne, aber mängi händ das für verunreinigend ghalte (vgl. [[ACT.10.28]]).",
  "Öb de Maa im Dienscht vom Antipas oder vo ere römische Hilfstruppe gstande isch, seit de Text nöd. Wie sträng d Scheu vor nöd-jüdische Hüüser dazmal gsii isch, isch umstritte.",
  ["Hauptme, Befelshaber über hundert", "Bueb; Diener"]),
 ("BG-MAT-2002", U(8, 18, 22), "MAT.8.21-MAT.8.22", GAL, "probable", "Die Pflicht, den Vater zu begraben",
  "Die Eltern zu begraben galt als eine der wichtigsten Pflichten der Kinder und als Teil des Gebots, Vater und Mutter zu ehren. Im Buch Tobit bittet der Vater den Sohn, ihn würdig zu begraben. Nach der Mischna ist, wessen Toter noch unbestattet vor ihm liegt, sogar vom Sprechen des «Höre, Israel» befreit. Nur der Hohepriester und wer ein Nasiräatsgelübde hatte, durften selbst für die Eltern keine Totenpflicht übernehmen ([[LEV.21.11]]; [[NUM.6.6-NUM.6.7]]). Bestattet wurde meist noch am Todestag. Elischa durfte sich von seinen Eltern verabschieden, bevor er Elija folgte ([[1KI.19.19-1KI.19.21]]); Jesu Antwort ist schärfer.",
  "Ob der Vater des Jüngers schon gestorben war oder ob der Jünger bis zum Tod des Vaters warten wollte, sagt der Text nicht. Eine These bezieht die Bitte auf die zweite Bestattung, bei der die Gebeine nach etwa einem Jahr in ein Knochenkästchen gelegt wurden; sie ist umstritten.",
  ["MAT.8.18-MAT.8.22", "LUK.9.57-LUK.9.62", "LEV.21.11", "NUM.6.6-NUM.6.7", "1KI.19.19-1KI.19.21"], ["Tobit 4,3–4", "Mischna, Berachot 3,1"],
  [("grc", "θάπτω", "begraben")],
  "D Pflicht, de Vatter z beerdige",
  "D Eltere z beerdige isch als eini vo de wichtigschte Pflichte vo de Chind gältet und als Teil vom Gebot, Vatter und Mueter z ehre. Im Buech Tobit bittet de Vatter de Sohn, en würdig z beerdige. Nach de Mischna isch, wär sin Tote no unbeerdiget vor sich hät, sogar vom Spräche vom «Lose, Israel» befreit. Nu de Hoheprieschter und wär es Nasiräer-Glübd gha hät, händ sälber für d Eltere kei Totepflicht dörfe übernää ([[LEV.21.11]]; [[NUM.6.6-NUM.6.7]]). Beerdiget hät me meischtens no am gliiche Tag. De Elischa hät sich vo sine Eltere dörfe verabschiede, bevor er em Elija gfolgt isch ([[1KI.19.19-1KI.19.21]]); d Antwort vo Jesus isch schärfer.",
  "Öb de Vatter vom Jünger scho gstorbe gsii isch oder öb de Jünger bis zum Tod vom Vatter hät wele warte, seit de Text nöd. E These bezieht d Bitt uf di zweit Beerdigung, wo me d Chnoche nach öppe eim Jaar in es Chnochechäschtli gleit hät; si isch umstritte.",
  ["beerdige"]),
 ("BG-MAT-2003", U(8, 28, 34), "MAT.8.28", GAL, "probable", "Gadara und die Schweine",
  "Gadara (heute Umm Qais in Jordanien) war eine griechisch geprägte Stadt der Dekapolis, etwa zehn Kilometer südöstlich des Sees Gennesaret, durch das Tal des Jarmuk von ihm getrennt. Ob ihr Gebiet bis ans Ufer reichte, ist nicht sicher belegt. Die Handschriften lesen bei Matthäus «Gadarener», «Gergesener» oder «Gerasener»; Markus und Lukas haben meist «Gerasener» (zu Gerasa und zur Dekapolis siehe BG-MRK-1008). Schweine galten nach der Tora als unrein ([[LEV.11.7]]; [[DEU.14.8]]); eine grosse Herde weist auf eine überwiegend nichtjüdische Gegend. Grabstätten galten als unreine Orte ([[NUM.19.16]]; vgl. [[ISA.65.4]]).",
  "Die Lage des Geschehens ist umstritten (QUESTION-MRK-1005). Die Entfernung von Gadara zum See ist eine Luftlinie; der Weg war länger.",
  ["MAT.8.28-MAT.8.34", "MRK.5.1", "LUK.8.26", "LEV.11.7", "DEU.14.8", "NUM.19.16"], [],
  [("grc", "Γαδαρηνός", "Bewohner von Gadara")],
  "Gadara und d Söi",
  "Gadara (hüt Umm Qais in Jordanie) isch e griechisch prägti Stadt vo de Dekapolis gsii, öppe zää Kilometer süüdöschtlich vom See Gennesaret, dur s Tal vom Jarmuk vo ihm trännt. Öb ires Gebiet bis as Ufer greicht hät, isch nöd sicher belegt. D Handschrifte läsed bim Matthäus «Gadarener», «Gergesener» oder «Gerasener»; de Markus und de Lukas händ meischtens «Gerasener» (zu Gerasa und zur Dekapolis lueg BG-MRK-1008). Söi händ nach de Tora als unrein gältet ([[LEV.11.7]]; [[DEU.14.8]]); e grossi Herde wiist uf e Gäged, wo mehrheitlich nöd-jüdisch gsii isch. Grabstätte händ als unreini Ort gältet ([[NUM.19.16]]; vgl. [[ISA.65.4]]).",
  "D Laag vom Gscheh isch umstritte (QUESTION-MRK-1005). D Entfärnig vo Gadara zum See isch Luftlinie; de Wäg isch länger gsii.",
  ["Bewoner vo Gadara"]),
 ("BG-MAT-2004", U(8, 5, 13), "MAT.8.11-MAT.8.12", READERS, "probable", "Das Festmahl der Heilszeit",
  "Die Hoffnung auf ein Festmahl, das Gott am Ende allen Völkern bereitet, geht auf [[ISA.25.6-ISA.25.8]] zurück; in jüdischen Texten der Zeit wird das Bild vielfach aufgenommen. Zu Tisch «liegen» (ἀνακλίνομαι) war die Haltung bei Festmählern: Man lag auf Polstern, auf den linken Arm gestützt. Mit Abraham, Isaak und Jakob zu Tisch zu liegen heisst, zur Familie der Erzväter zu gehören. Das Gegenbild ist die «äussere Finsternis», draussen vor dem erleuchteten Festsaal ([[MAT.8.12]]; [[MAT.22.13]]; [[MAT.25.30]]); «Weinen und Zähneknirschen» bezeichnet Klage und ohnmächtige Wut.",
  "Wie weit das Mahlbild zur Zeit Jesu verbreitet war und wer daran teilhaben sollte (Israel allein oder auch die Völker), wird in den Quellen unterschiedlich gesehen.",
  ["ISA.25.6-ISA.25.8", "MAT.8.11-MAT.8.12", "MAT.22.1-MAT.22.14", "MAT.26.29", "LUK.13.28-LUK.13.29"], [],
  [("grc", "ἀνακλίνομαι", "sich zu Tisch legen"), ("grc", "σκότος τὸ ἐξώτερον", "die äussere Finsternis")],
  "S Feschtmahl vo de Heilsziit",
  "D Hoffnig uf es Feschtmahl, wo Gott am Änd allne Völker bereitet, gaat uf [[ISA.25.6-ISA.25.8]] zrugg; i jüdische Text vo dere Ziit wird s Bild vilfach uufgnoo. Z Tisch «ligge» (ἀνακλίνομαι) isch d Haltig bi Feschtmähler gsii: Me isch uf Polschter gläge, uf de linggi Arm gstützt. Mit em Abraham, em Isaak und em Jakob z Tisch z ligge heisst, zur Familie vo de Erzvätter z ghööre. S Gägebild isch di «üsseri Finschternis», dusse vor em hälle Feschtsaal ([[MAT.8.12]]; [[MAT.22.13]]; [[MAT.25.30]]); «Hüüle und Zääneknirsche» bezeichnet Chlag und ohnmächtigi Wuet.",
  "Wie wiit s Mahlbild zur Ziit vo Jesus verbreitet gsii isch und wär dra hett sölle teilhaa (Israel elei oder au d Völker), wird i de Quälle verschide gseh.",
  ["sich z Tisch legge", "di üsseri Finschternis"]),
 ("BG-MAT-2005", U(9, 14, 17), "MAT.9.14-MAT.9.15", READERS, "probable", "Fasten",
  "Die Tora schreibt nur für den Versöhnungstag vor, «sich zu demütigen», was als Fasten verstanden wurde ([[LEV.16.29-LEV.16.31]]); dazu kamen Gedenkfasten ([[ZEC.8.19]]) und freiwilliges Fasten in Trauer, Busse oder Gebet. Nach [[LUK.18.12]] fastet ein Pharisäer zweimal in der Woche. Die Didache, eine frühchristliche Schrift, mahnt: Die «Heuchler» fasten am Montag und Donnerstag, ihr aber fastet am Mittwoch und Freitag. Fasten gehörte auch zur Trauer; dass Hochzeitsgäste während der Hochzeit nicht trauern, war selbstverständlich ([[MAT.9.15]]).",
  "Ob die Fasttage Montag und Donnerstag schon zur Zeit Jesu üblich waren, ist aus der Didache (wohl um 100 n. Chr.) erschlossen.",
  ["LEV.16.29-LEV.16.31", "ZEC.8.19", "LUK.18.12", "MAT.6.16-MAT.6.18", "MAT.9.14-MAT.9.17"], ["Didache 8,1"],
  [("grc", "νηστεύω", "fasten"), ("grc", "νυμφών", "Brautgemach; οἱ υἱοὶ τοῦ νυμφῶνος: die Hochzeitsgäste")],
  "Faschte",
  "D Tora schriibt nu für de Versöönigstag vor, «sich z demüetige», was als Faschte verstande worde isch ([[LEV.16.29-LEV.16.31]]); dezue sind Gedänkfaschte cho ([[ZEC.8.19]]) und freiwilligs Faschte i Truur, Buess oder Gebätt. Nach [[LUK.18.12]] faschtet en Pharisäer zwei Mal i de Wuche. D Didache, e früechrischtlichi Schrift, mahnt: D «Heuchler» faschted am Määntig und am Dunschtig, ir aber faschted am Mittwuch und am Friitig. Faschte hät au zur Truur ghört; dass Hochsigsgäscht wäred de Hochsig nöd truured, isch sälbverständlich gsii ([[MAT.9.15]]).",
  "Öb d Faschttäg Määntig und Dunschtig scho zur Ziit vo Jesus üeblich gsii sind, isch us de Didache (wahrschiinli um 100 n. Chr.) erschlosse.",
  ["faschte", "Bruutgmach; οἱ υἱοὶ τοῦ νυμφῶνος: d Hochsigsgäscht"]),
 ("BG-MAT-2006", U(9, 18, 26), "MAT.9.23", GAL, "probable", "Flötenspieler und Klage",
  "Zur Totenklage gehörten Flötenspieler und Klagefrauen, die gegen Lohn klagten (vgl. [[JER.9.17-JER.9.18]]). Nach einem Ausspruch von Rabbi Jehuda in der Mischna soll selbst der Ärmste in Israel für die Bestattung seiner Frau nicht weniger als zwei Flöten und eine Klagefrau bestellen. Dass bei einem Vorsteher (ἄρχων) schon Flötenspieler und eine lärmende Menge im Haus sind ([[MAT.9.23]]), zeigt, dass die Trauer begonnen hat; bestattet wurde meist noch am selben Tag.",
  "Die Mischna wurde um 200 n. Chr. gesammelt; der Brauch ist aber auch biblisch und ausserbiblisch früher bezeugt.",
  ["MAT.9.23-MAT.9.25", "JER.9.17-JER.9.18", "MRK.5.38"], ["Mischna, Ketubbot 4,4"],
  [("grc", "αὐλητής", "Flötenspieler"), ("grc", "ἄρχων", "Vorsteher, Oberster")],
  "Flöötespiler und Chlag",
  "Zur Toteklag händ Flöötespiler und Chlagfraue ghört, wo gäge Loon gchlagt händ (vgl. [[JER.9.17-JER.9.18]]). Nach eme Uusspruch vom Rabbi Jehuda i de Mischna söll sogar de Ärmscht in Israel für d Beerdigung vo sinere Frau nöd weniger als zwei Flööte und ei Chlagfrau bstelle. Dass bi me Vorsteher (ἄρχων) scho Flöötespiler und e lärmigi Mängi im Huus sind ([[MAT.9.23]]), zeigt, dass d Truur aagfange hät; beerdiget hät me meischtens no am gliiche Tag.",
  "D Mischna isch um 200 n. Chr. gsammlet worde; de Bruuch isch aber au biblisch und usserbiblisch früener bezüüget.",
  ["Flöötespiler", "Vorsteher, Oberschte"]),
 ("BG-MAT-2007", U(9, 18, 26), "MAT.9.20", READERS, "probable", "Quasten am Mantel",
  "Die Tora gebietet, an den vier Ecken des Obergewands Quasten zu tragen, die an die Gebote erinnern ([[NUM.15.38-NUM.15.40]]; [[DEU.22.12]]). Die griechische Übersetzung von [[NUM.15.38]] gebraucht dafür dasselbe Wort κράσπεδον, das Matthäus in [[MAT.9.20]] und [[MAT.14.36]] hat; gemeint ist dann nicht ein beliebiger Saum, sondern die Quaste. Nach [[MAT.23.5]] machen die Pharisäer ihre Quasten gross. Die blutflüssige Frau galt nach [[LEV.15.25-LEV.15.27]] als unrein, und wer sie berührte, ebenso bis zum Abend. Matthäus erwähnt das nicht.",
  "Dass κράσπεδον in [[MAT.9.20]] die Quaste meint, ist wahrscheinlich, aber nicht sicher; das Wort kann allgemein «Rand, Saum» heissen. Die Septuaginta ist nicht in den Daten.",
  ["NUM.15.38-NUM.15.40", "DEU.22.12", "LEV.15.25-LEV.15.27", "MAT.9.20", "MAT.14.36", "MAT.23.5"], [],
  [("grc", "κράσπεδον", "Saum, Quaste"), ("heb", "צִיצִת", "Quaste (an den Ecken des Gewands)", "ṣîṣit")],
  "Quaschte am Mantel",
  "D Tora befiilt, a de vier Egge vom Obergwand Quaschte z träge, wo a d Gebot erinnered ([[NUM.15.38-NUM.15.40]]; [[DEU.22.12]]). Di griechisch Übersetzig vo [[NUM.15.38]] bruucht defür s gliich Wort κράσπεδον, wo de Matthäus i [[MAT.9.20]] und [[MAT.14.36]] hät; gmeint isch dänn nöd en beliebige Saum, sondern d Quaschte. Nach [[MAT.23.5]] mached d Pharisäer iri Quaschte gross. D Frau mit em Bluetfluss hät nach [[LEV.15.25-LEV.15.27]] als unrein gältet, und wär si berüert hät, au, bis am Aabig. De Matthäus erwäänt das nöd.",
  "Dass κράσπεδον i [[MAT.9.20]] d Quaschte meint, isch wahrschiinli, aber nöd sicher; s Wort cha allgemein «Rand, Saum» heisse. D Septuaginta isch nöd i de Date.",
  ["Saum, Quaschte", "Quaschte (a de Egge vom Gwand)"]),
 ("BG-MAT-2008", U(9, 27, 31), "MAT.9.27", READERS, "probable", "Der «Sohn Davids»",
  "Nach der Verheissung an David sollte einer seiner Nachkommen für immer König sein ([[2SA.7.12-2SA.7.16]]; vgl. [[ISA.11.1-ISA.11.5]]; [[JER.23.5]]). In den Psalmen Salomos, einer jüdischen Schrift des 1. Jahrhunderts v. Chr., wird Gott gebeten, Israel «ihren König, den Sohn Davids» zu erwecken. Dieser erwartete König ist dort ein gerechter Herrscher, kein Heiler. Zugleich galt Davids Sohn Salomo als Meister über Krankheiten und Dämonen: Josephus erzählt von Beschwörungen, die auf Salomo zurückgeführt wurden.",
  "Ob Matthäus beim Heilen des «Sohnes Davids» an Salomo denkt, ist eine umstrittene These; sicher ist nur, dass er den Titel bewusst mit Heilungen verbindet (FIND-MAT-2006).",
  ["2SA.7.12-2SA.7.16", "ISA.11.1-ISA.11.5", "JER.23.5", "MAT.1.1", "MAT.9.27", "MAT.12.23"], ["Psalmen Salomos 17,21", "Josephus, Jüdische Altertümer 8,45–49"],
  [("grc", "υἱὸς Δαυίδ", "Sohn Davids"), ("heb", "בֶּן־דָּוִד", "Sohn Davids", "ben dāwid")],
  "De «Sohn vo David»",
  "Nach de Verheissig a de David söll eine vo sine Nachkomme für immer König sii ([[2SA.7.12-2SA.7.16]]; vgl. [[ISA.11.1-ISA.11.5]]; [[JER.23.5]]). I de Psalme vom Salomo, ere jüdische Schrift us em 1. Jaarhundert v. Chr., wird Gott bätte, er söll Israel «ire König, de Sohn vo David» erwecke. Dä erwartet König isch det en grächte Herrscher, kein Heiler. Zuglich hät em David sin Sohn Salomo als Meischter über Chrankete und Dämone gältet: De Josephus verzellt vo Beschwöörige, wo me uf de Salomo zrugggfüert hät.",
  "Öb de Matthäus bim Heile vom «Sohn vo David» a de Salomo dänkt, isch e umstritteni These; sicher isch nu, dass er de Titel bewusst mit Heilige verbindet (FIND-MAT-2006).",
  ["Sohn vo David", "Sohn vo David"]),
 ("BG-MAT-2009", U(10, 1, 4), "MAT.10.1-MAT.10.4", READERS, "probable", "Zwölf Jünger und zwölf Stämme",
  "Die Zahl zwölf erinnert an die zwölf Stämme Israels. Zur Zeit Jesu bestanden die meisten Stämme nicht mehr als eigene Gruppen; die Hoffnung, Gott werde die Stämme Jakobs wieder aufrichten, war aber lebendig ([[ISA.49.6]]; vgl. [[EZK.47.13]]). Matthäus macht den Bezug ausdrücklich: Die Zwölf werden auf zwölf Thronen sitzen und die zwölf Stämme Israels richten ([[MAT.19.28]]). Auch die Gemeinschaft von Qumran kannte einen Rat von zwölf Männern und drei Priestern.",
  "Wie die Qumran-Stelle zu deuten ist (zwölf neben oder einschliesslich der drei Priester), ist umstritten.",
  ["MAT.10.1-MAT.10.4", "MAT.19.28", "ISA.49.6", "EZK.47.13"], ["Gemeinderegel aus Qumran (1QS) 8,1"],
  [("grc", "δώδεκα", "zwölf"), ("grc", "φυλή", "Stamm")],
  "Zwölf Jünger und zwölf Stämm",
  "D Zaal zwölf erinneret a di zwölf Stämm vo Israel. Zur Ziit vo Jesus händ di meischte Stämm nüme als eigeti Gruppe bestande; d Hoffnig, Gott werdi d Stämm vo Jakob wider uufrichte, isch aber läbig gsii ([[ISA.49.6]]; vgl. [[EZK.47.13]]). De Matthäus macht de Bezug usdrücklich: Di Zwölf wärded uf zwölf Throon sitze und di zwölf Stämm vo Israel richte ([[MAT.19.28]]). Au d Gmeinschaft vo Qumran hät en Root vo zwölf Manne und drüü Prieschter kännt.",
  "Wie d Qumran-Stell z düüte isch (zwölf näbe oder mitsamt de drüü Prieschter), isch umstritte.",
  ["zwölf", "Stamm"]),
 ("BG-MAT-2010", U(10, 5, 15), "MAT.10.5", GAL, "probable", "Samaritaner",
  "Die Samaritaner lebten im Bergland zwischen Galiläa und Judäa. Sie verehrten den Gott Israels und hielten die fünf Bücher Mose, hatten aber ihr Heiligtum auf dem Berg Garizim. Juden sahen sie oft als Mischvolk an (vgl. [[2KI.17.24-2KI.17.41]]). Der Hasmonäer Johannes Hyrkanos eroberte im späten 2. Jahrhundert v. Chr. Sichem und den Garizim; nach Josephus war ihr Tempel dort danach verödet. Zur Zeit Jesu kam es auf dem Weg der Festpilger durch Samaria immer wieder zu Feindseligkeiten (vgl. [[LUK.9.52-LUK.9.53]]; [[JHN.4.9]]). Matthäus erwähnt Samaritaner nur in [[MAT.10.5]].",
  "Die Herkunft der Samaritaner und der Zeitpunkt der Trennung sind in der Forschung umstritten; [[2KI.17.24-2KI.17.41]] gibt die Sicht von Judäa wieder. Dass Hyrkanos den Tempel selbst zerstörte, sagt Josephus an der Stelle nicht ausdrücklich; es wird daraus geschlossen.",
  ["MAT.10.5", "2KI.17.24-2KI.17.41", "LUK.9.52-LUK.9.53", "JHN.4.9", "JHN.4.20"], ["Josephus, Jüdische Altertümer 13,254–256"],
  [("grc", "Σαμαρίτης", "Samaritaner")],
  "Samaritaner",
  "D Samaritaner händ im Bärgland zwüsche Galiläa und Judäa gläbt. Si händ de Gott vo Israel verehrt und d föif Büecher vom Mose ghalte, händ aber ires Heiligtum uf em Bärg Garizim gha. Jude händ si oft als Mischvolk aagluegt (vgl. [[2KI.17.24-2KI.17.41]]). De Hasmonäer Johannes Hyrkanos hät im spoote 2. Jaarhundert v. Chr. Sichem und de Garizim erobert; nach em Josephus isch ire Tämpel det dänn verödet gsii. Zur Ziit vo Jesus isch es uf em Wäg vo de Feschtpilger dur Samaria immer wider zu Findseligkeite cho (vgl. [[LUK.9.52-LUK.9.53]]; [[JHN.4.9]]). De Matthäus erwäänt Samaritaner nu i [[MAT.10.5]].",
  "D Härkunft vo de Samaritaner und de Ziitpunkt vo de Trännig sind i de Forschig umstritte; [[2KI.17.24-2KI.17.41]] git d Sicht vo Judäa wider. Dass de Hyrkanos de Tämpel sälber zerstöört hät, seit de Josephus a dere Stell nöd usdrücklich; me schlüüsst s drus.",
  ["Samaritaner"]),
 ("BG-MAT-2011", U(10, 5, 15), "MAT.10.9-MAT.10.14", GAL, "probable", "Ausrüstung, Gastfreundschaft und Staub",
  "Reisende trugen Geld im Gürtel, einen Beutel (πήρα) für Vorräte, Sandalen und einen Stab zum Gehen und zur Abwehr. Die Boten sollen auf all das verzichten und von der Gastfreundschaft leben; Gastfreundschaft galt im Judentum als hohe Pflicht. Josephus berichtet von den Essenern, sie nähmen auf Reisen nichts mit ausser Waffen gegen Räuber und fänden in jeder Stadt Unterkunft bei Gleichgesinnten. Nach der Mischna durfte man den Tempelberg nicht mit Stab, Schuhen, Geldgürtel oder Staub an den Füssen betreten. Den Staub von den Füssen zu schütteln ([[MAT.10.14]]; vgl. [[ACT.13.51]]) ist eine Zeichenhandlung der Trennung.",
  "Ob die Ausrüstungsregel bewusst an die Vorschrift für den Tempelberg erinnert, ist eine Vermutung. Dass das Abschütteln an die Vorstellung anknüpft, Boden ausserhalb Israels sei unrein, wird oft gesagt; die Belege dafür sind später.",
  ["MAT.10.9-MAT.10.14", "MRK.6.8-MRK.6.11", "LUK.9.3-LUK.9.5", "LUK.10.4-LUK.10.11", "ACT.13.51"],
  ["Josephus, Jüdischer Krieg 2,124–127", "Mischna, Berachot 9,5"],
  [("grc", "πήρα", "Beutel, Reisetasche"), ("grc", "ζώνη", "Gürtel (auch als Geldbeutel)")],
  "Uusrüschtig, Gaschtfründschaft und Staub",
  "Reisendi händ Gält im Gurt treit, en Büütel (πήρα) für Vorrööt, Sandale und en Stäcke zum Laufe und zum Abwehre. D Bote söled uf all das verzichte und vo de Gaschtfründschaft läbe; Gaschtfründschaft hät im Judetum als hohi Pflicht gältet. De Josephus bricht vo de Essener, si nämed uf Reise nüüt mit ussert Waffe gäge Röiber und fänded i jeder Stadt Underkunft bi Gliichgsinnte. Nach de Mischna hät me de Tämpelbärg nöd mit Stäcke, Schue, Gältgurt oder Staub a de Füess dörfe beträtte. De Staub vo de Füess z schüttle ([[MAT.10.14]]; vgl. [[ACT.13.51]]) isch e Zeichehandlig vo de Trännig.",
  "Öb d Uusrüschtigsregle bewusst a d Vorschrift für de Tämpelbärg erinneret, isch e Vermuetig. Dass s Abschüttle a d Vorstellig aaknüpft, de Bode usserhalb vo Israel seg unrein, wird oft gseit; d Beleg defür sind spööter.",
  ["Büütel, Reisetäsche", "Gurt (au als Gältsäckli)"]),
 ("BG-MAT-2012", U(10, 16, 25), "MAT.10.17", READERS, "probable", "Geisselung in Synagogen",
  "Die Synagoge war nicht nur Ort für Gebet und Lesung, sondern auch für die örtliche Rechtsprechung. Die Tora erlaubt bei bestimmten Vergehen Schläge, höchstens vierzig ([[DEU.25.1-DEU.25.3]]). Nach der Mischna wurden «vierzig weniger einer» gegeben, und ein Diener der Synagoge vollzog die Strafe. Paulus schreibt, er habe fünfmal «vierzig weniger einen» Schlag von Juden erhalten ([[2CO.11.24]]). Die «Gerichte» (συνέδρια) in [[MAT.10.17]] sind örtliche Räte, nicht nur der Hohe Rat in Jerusalem.",
  "Wie die Mischna-Regeln (um 200 n. Chr. gesammelt) dem Verfahren des 1. Jahrhunderts entsprechen, ist nicht im Einzelnen bekannt.",
  ["MAT.10.17", "MAT.23.34", "DEU.25.1-DEU.25.3", "2CO.11.24", "ACT.22.19"], ["Mischna, Makkot 3,10–12"],
  [("grc", "μαστιγόω", "geisseln, auspeitschen"), ("grc", "συνέδριον", "Ratsversammlung, Gericht")],
  "Gaisslig i Synagoge",
  "D Synagoge isch nöd nu de Ort für Gebätt und Läsig gsii, sondern au für s örtlich Gricht. D Tora erlaubt bi bestimmte Vergehe Schleg, höchschtens vierzg ([[DEU.25.1-DEU.25.3]]). Nach de Mischna hät me «vierzg weniger eine» ggää, und en Diener vo de Synagoge hät d Straf vollzoge. De Paulus schriibt, er heig föif Mal «vierzg weniger eine» Schlag vo Jude übercho ([[2CO.11.24]]). D «Grichtshöf» (συνέδρια) i [[MAT.10.17]] sind örtlichi Rööt, nöd nu de Hohi Root z Jerusalem.",
  "Wie d Mischna-Regle (um 200 n. Chr. gsammlet) em Verfaare vom 1. Jaarhundert entspräched, weiss me nöd im einzelne.",
  ["gaissle, uuspitsche", "Rootsversammlig, Gricht"]),
 ("BG-MAT-2013", U(10, 26, 33), "MAT.10.28", READERS, "probable", "Gehenna",
  "Das Wort, das die Arbeitsübersetzung mit «Hölle» wiedergibt, ist γέεννα, nach dem hebräischen «Tal Hinnom» südlich von Jerusalem ([[JOS.15.8]]). Dort wurden in der Königszeit Kinder geopfert, was die Propheten verurteilten ([[2KI.23.10]]; [[JER.7.31-JER.7.32]]). In jüdischen Texten um die Zeitenwende wurde der Name zum Bild für den Ort des endgültigen Gerichts. Matthäus hat γέεννα sieben Mal, so oft wie kein anderes Buch des Neuen Testaments; in [[MAT.10.28]] ist Gott derjenige, der «Seele und Leib» darin verderben kann.",
  "Die oft wiederholte Erklärung, im Tal Hinnom habe zur Zeit Jesu eine ständig brennende Müllhalde gelegen, stammt aus viel späterer Zeit und ist nicht gesichert.",
  ["JOS.15.8", "2KI.23.10", "JER.7.31-JER.7.32", "MAT.5.22", "MAT.10.28", "MAT.23.33"], [],
  [("grc", "γέεννα", "Gehenna, Ort des Gerichts"), ("heb", "גֵּי הִנֹּם", "Tal Hinnom", "gê hinnōm")],
  "Gehenna",
  "S Wort, wo d Arbetsübersetzig mit «Höll» widergit, isch γέεννα, nach em hebräische «Tal Hinnom» süüdlich vo Jerusalem ([[JOS.15.8]]). Det sind i de Königsziit Chind gopferet worde, was d Prophete verurteilt händ ([[2KI.23.10]]; [[JER.7.31-JER.7.32]]). I jüdische Text um d Ziitewändi isch de Name zum Bild für de Ort vom ändgültige Gricht worde. De Matthäus hät γέεννα siebe Mal, so oft wie kein anders Buech vom Nöie Teschtament; i [[MAT.10.28]] isch Gott dä, wo «Seel und Liib» drin cha verderbe.",
  "Di oft widerholt Erklärig, im Tal Hinnom seg zur Ziit vo Jesus e Abfallhalde gsii, wo immer brännt heig, stammt us vil spöötere Ziit und isch nöd gsicheret.",
  ["Gehenna, Ort vom Gricht", "Tal Hinnom"]),
 ("BG-MAT-2014", U(11, 1, 6), "MAT.11.2", GAL, "probable", "Johannes im Gefängnis",
  "Matthäus erwähnt die Gefangennahme des Johannes schon in [[MAT.4.12]] und erzählt sie erst in [[MAT.14.3-MAT.14.4]]. Wo Johannes gefangen sass, sagen die Evangelien nicht. Nach Josephus liess Herodes Antipas ihn in die Festung Machärus östlich des Toten Meeres bringen und dort töten, weil er fürchtete, der Einfluss des Täufers auf das Volk könne zu einem Aufstand führen. Gefangene waren auf Besucher angewiesen, die sie mit Nahrung versorgten; so erklärt sich, dass die Jünger des Johannes mit ihm in Verbindung stehen ([[MAT.11.2]]).",
  "Josephus nennt einen anderen Grund für die Hinrichtung als die Evangelien (Herodias); beide Begründungen schliessen sich nicht aus. Zur Familie des Herodes siehe BG-MRK-1009.",
  ["MAT.4.12", "MAT.11.2-MAT.11.3", "MAT.14.3-MAT.14.12"], ["Josephus, Jüdische Altertümer 18,116–119"],
  [("grc", "δεσμωτήριον", "Gefängnis")],
  "De Johannes im Gfängnis",
  "De Matthäus erwäänt d Gfangenaam vom Johannes scho i [[MAT.4.12]] und verzellt si erscht i [[MAT.14.3-MAT.14.4]]. Wo de Johannes gfange gsässe isch, säged d Evangelie nöd. Nach em Josephus hät de Herodes Antipas en i d Feschtig Machärus öschtlich vom Tote Meer bringe und det töte loo, wil er gfürchtet hät, de Iifluss vom Täufer uf s Volk chönn zumene Uufstand füere. Gfangni sind uf Bsuecher aagwise gsii, wo si mit Ässe versorgt händ; so erklärt sich, dass d Jünger vom Johannes mit ihm in Verbindig stönd ([[MAT.11.2]]).",
  "De Josephus nännt en andere Grund für d Hiirichtig als d Evangelie (Herodias); beidi Begründige schlüüssed sich nöd uus. Zur Familie vom Herodes lueg BG-MRK-1009.",
  ["Gfängnis"]),
 ("BG-MAT-2015", U(11, 1, 6), "MAT.11.3-MAT.11.5", READERS, "probable", "Der «Kommende» und die Zeichen der Heilszeit",
  "Johannes hatte einen «Kommenden» angekündigt, der stärker ist als er ([[MAT.3.11]]); «der kommt im Namen des Herrn» steht in [[PSA.118.26]] und wird beim Einzug in Jerusalem gerufen ([[MAT.21.9]]). Jesu Antwort nimmt Verheissungen aus Jesaja auf ([[ISA.35.5-ISA.35.6]]; [[ISA.26.19]]; [[ISA.61.1]]). Ein Text aus Qumran (4Q521) verbindet ähnliche Zeichen mit dem Messias: Himmel und Erde würden auf «seinen Gesalbten» hören, und der Herr werde Verwundete heilen, Tote lebendig machen und den Armen gute Botschaft bringen. Die Antwort an Johannes bewegt sich damit in einer bekannten Erwartung.",
  "4Q521 ist nur bruchstückhaft erhalten; wer dort heilt und Tote erweckt (Gott selbst oder sein Gesalbter), ist umstritten.",
  ["MAT.3.11", "MAT.11.3-MAT.11.6", "PSA.118.26", "ISA.35.5-ISA.35.6", "ISA.26.19", "ISA.61.1"], ["Qumran, 4Q521 Fragment 2, Kolumne 2"],
  [("grc", "ὁ ἐρχόμενος", "der Kommende")],
  "De «Kommendi» und d Zeiche vo de Heilsziit",
  "De Johannes hät en «Kommende» aagchündt, wo stercher isch als er ([[MAT.3.11]]); «wo chunnt im Name vom Herr» staat i [[PSA.118.26]] und wird bim Iizug in Jerusalem grüeft ([[MAT.21.9]]). D Antwort vo Jesus nimmt Verheissige us em Jesaja uf ([[ISA.35.5-ISA.35.6]]; [[ISA.26.19]]; [[ISA.61.1]]). En Text us Qumran (4Q521) verbindet ähnlichi Zeiche mit em Messias: Himel und Ärde wärded uf «sin Gsalbte» lose, und de Herr werdi Verwundeti heile, Toti läbig mache und de Arme e gueti Botschaft bringe. D Antwort a de Johannes bewegt sich dämit in ere bekannte Erwartig.",
  "4Q521 isch nu stuckwiis erhalte; wär det heilt und Toti uferweckt (Gott sälber oder sin Gsalbte), isch umstritte.",
  ["de Kommendi"]),
 ("BG-MAT-2016", U(11, 7, 15), "MAT.11.14", READERS, "probable", "Die Erwartung des Elija",
  "Das Buch Maleachi schliesst mit der Verheissung: «Ich sende euch den Propheten Elija, bevor der Tag des HERRN kommt» ([[MAL.4.5-MAL.4.6]]). Jesus Sirach nennt Elija den, der bereitsteht, die Stämme Jakobs wiederherzustellen. Johannes trägt Kleidung wie Elija ([[MAT.3.4]]; [[2KI.1.8]]). Jesus nennt ihn in [[MAT.11.14]] Elija, «wenn ihr es annehmen wollt», und wiederholt das nach der Verklärung ([[MAT.17.10-MAT.17.13]]). In [[MAT.11.10]] wird zuvor [[MAL.3.1]] zitiert, mit Anklang an [[EXO.23.20]] (vgl. FIND-MRK-1001).",
  "Ob Elija zur Zeit Jesu allgemein als Vorläufer des Messias oder eher als Vorbote Gottes selbst erwartet wurde, ist umstritten.",
  ["MAL.3.1", "MAL.4.5-MAL.4.6", "MAT.3.4", "2KI.1.8", "MAT.11.10-MAT.11.14", "MAT.17.10-MAT.17.13"], ["Jesus Sirach 48,10"],
  [("grc", "Ἠλίας", "Elija")],
  "D Erwartig vom Elija",
  "S Buech Maleachi hört uf mit de Verheissig: «Ich schick eu de Prophet Elija, bevor de Tag vom HERR chunnt» ([[MAL.4.5-MAL.4.6]]). De Jesus Sirach nännt de Elija dä, wo parat staat, d Stämm vo Jakob wider herzstelle. De Johannes treit Chleider wie de Elija ([[MAT.3.4]]; [[2KI.1.8]]). De Jesus nännt en i [[MAT.11.14]] Elija, «wänn er s wänd aanää», und widerholt das nach de Verklärig ([[MAT.17.10-MAT.17.13]]). I [[MAT.11.10]] wird vorher [[MAL.3.1]] zitiert, mit Aaklang a [[EXO.23.20]] (vgl. FIND-MRK-1001).",
  "Öb de Elija zur Ziit vo Jesus allgemein als Vorlöiffer vom Messias oder eher als Vorbot vo Gott sälber erwartet worde isch, isch umstritte.",
  ["Elija"]),
 ("BG-MAT-2017", U(11, 25, 30), "MAT.11.29-MAT.11.30", READERS, "probable", "Das Joch",
  "Ein Joch legte man Zugtieren auf, damit sie gemeinsam ziehen; im übertragenen Sinn steht es für Herrschaft und Dienst ([[JER.5.5]]; [[LAM.3.27]]). Jüdische Lehrer sprachen vom «Joch der Tora» und vom «Joch des Himmelreichs», das man mit dem «Höre, Israel» auf sich nimmt; das war positiv gemeint: Wer es trägt, wird von anderen Lasten frei. Am Schluss des Buches Jesus Sirach lädt der Lehrer ein, den Nacken unter das Joch der Weisheit zu beugen, und sagt, er selbst habe mit wenig Mühe viel Ruhe gefunden. Nach [[ACT.15.10]] nennt Petrus das Gesetz ein Joch, das niemand tragen konnte.",
  "Die Mischna wurde um 200 n. Chr. gesammelt; die Redeweise ist älter, ihr Alter im Einzelnen aber nicht sicher.",
  ["MAT.11.28-MAT.11.30", "JER.5.5", "LAM.3.27", "ACT.15.10", "MAT.23.4"], ["Mischna, Berachot 2,2", "Mischna, Avot 3,5", "Jesus Sirach 51,23–27"],
  [("grc", "ζυγός", "Joch"), ("heb", "עֹל", "Joch", "ʿōl")],
  "S Joch",
  "Es Joch hät me Zugtier uufgleit, demit si zäme zieed; im übertreite Sinn staat s für Herrschaft und Dienscht ([[JER.5.5]]; [[LAM.3.27]]). Jüdischi Leerer händ vom «Joch vo de Tora» und vom «Joch vom Himelriich» gredt, wo me mit em «Lose, Israel» uf sich nimmt; das isch positiv gmeint gsii: Wär s treit, wird vo andere Lascht frei. Am Schluss vom Buech Jesus Sirach laadt de Leerer ii, de Nacke under s Joch vo de Wiisheit z bücke, und seit, er sälber heig mit weni Müe vil Rue gfunde. Nach [[ACT.15.10]] nännt de Petrus s Gsetz es Joch, wo niemert hät chöne träge.",
  "D Mischna isch um 200 n. Chr. gsammlet worde; d Redewiis isch elter, wie alt genau, isch aber nöd sicher.",
  ["Joch", "Joch"]),
 ("BG-MAT-2018", U(11, 20, 24), "MAT.11.21-MAT.11.23", GAL, "probable", "Chorazin, Betsaida und Kafarnaum",
  "Chorazin wird im Neuen Testament nur in [[MAT.11.21]] und [[LUK.10.13]] genannt; man sucht es in den Ruinen von Khirbet Karazeh, etwa drei Kilometer nördlich von Kafarnaum, deren sichtbare Bauten aus späterer Zeit stammen. Betsaida lag am Nordufer nahe der Jordanmündung im Gebiet des Philippus, der den Ort zur Stadt Julias erhob; ob es bei et-Tell oder el-Araj lag, ist umstritten. Kafarnaum nennt Matthäus Jesu «eigene Stadt» ([[MAT.9.1]]; vgl. [[MAT.4.13]]). «Bis zum Himmel erhöht … bis ins Totenreich» klingt an das Spottlied auf den König von Babel an ([[ISA.14.13-ISA.14.15]]). Tyrus und Sidon waren phönizische Handelsstädte, gegen die die Propheten Gerichtsworte richteten ([[ISA.23.1-ISA.23.18]]; [[EZK.28.1-EZK.28.23]]). «Sack und Asche» sind Zeichen der Trauer und Busse ([[JON.3.6]]).",
  "Die Lage von Betsaida ist weiterhin umstritten; auch bei Chorazin ist die Gleichsetzung mit Khirbet Karazeh nur wahrscheinlich.",
  ["MAT.4.13", "MAT.9.1", "MAT.11.20-MAT.11.24", "LUK.10.13-LUK.10.15", "ISA.14.13-ISA.14.15", "JON.3.6"], ["Josephus, Jüdische Altertümer 18,28"],
  [("grc", "σάκκος", "Sack, Trauergewand aus grobem Stoff")],
  "Chorazin, Betsaida und Kafarnaum",
  "Chorazin wird im Nöie Teschtament nu i [[MAT.11.21]] und [[LUK.10.13]] gnännt; me sueched s i de Ruine vo Khirbet Karazeh, öppe drüü Kilometer nördlich vo Kafarnaum, wo di sichtbare Baute us spööterer Ziit stammed. Betsaida isch am Nordufer nööch bi de Jordanmündig im Gebiet vom Philippus gläge, wo de Ort zur Stadt Julias gmacht hät; öb s bi et-Tell oder el-Araj gläge isch, isch umstritte. Kafarnaum nännt de Matthäus em Jesus sini «eigeti Stadt» ([[MAT.9.1]]; vgl. [[MAT.4.13]]). «Bis zum Himel ufe … bis is Toteriich abe» klingt as Spottlied uf de König vo Babel aa ([[ISA.14.13-ISA.14.15]]). Tyrus und Sidon sind phönizischi Handelsstedt gsii, gäge die d Prophete Grichtswort grichtet händ ([[ISA.23.1-ISA.23.18]]; [[EZK.28.1-EZK.28.23]]). «Sack und Äsche» sind Zeiche vo Truur und Buess ([[JON.3.6]]).",
  "D Laag vo Betsaida isch immer no umstritte; au bi Chorazin isch d Gliichsetzig mit Khirbet Karazeh nu wahrschiinli.",
  ["Sack, Truurgwand us grobem Stoff"]),
 ("BG-MAT-2019", U(12, 1, 8), "MAT.12.4-MAT.12.5", READERS, "probable", "Schaubrote und Priesterdienst am Sabbat",
  "Im Heiligtum lagen zwölf Brote vor Gott, die jeden Sabbat erneuert und von den Priestern gegessen wurden ([[LEV.24.5-LEV.24.9]]). David erhielt in Nob solche Brote ([[1SA.21.1-1SA.21.6]]). Am Sabbat brachten die Priester zusätzliche Opfer dar ([[NUM.28.9-NUM.28.10]]); sie arbeiteten also im Tempel, ohne den Sabbat zu brechen. Spätere rabbinische Texte formulieren den Grundsatz, dass der Tempeldienst den Sabbat verdrängt. Jesu Argument «Hier ist Grösseres als der Tempel» ([[MAT.12.6]]) setzt diese Ausnahme voraus. Zum Sabbat allgemein siehe BG-MRK-1006.",
  "Wie weit die späteren rabbinischen Formulierungen die Auslegung zur Zeit Jesu wiedergeben, ist nicht sicher.",
  ["LEV.24.5-LEV.24.9", "1SA.21.1-1SA.21.6", "NUM.28.9-NUM.28.10", "MAT.12.3-MAT.12.6"], [],
  [("grc", "ἄρτοι τῆς προθέσεως", "Schaubrote, Brote der Auslegung"), ("grc", "βεβηλόω", "entweihen")],
  "Schaubroot und Prieschterdienscht am Sabbat",
  "Im Heiligtum sind zwölf Broot vor Gott gläge, wo me jede Sabbat erneueret hät und wo d Prieschter ggässe händ ([[LEV.24.5-LEV.24.9]]). De David hät z Nob settigi Broot übercho ([[1SA.21.1-1SA.21.6]]). Am Sabbat händ d Prieschter zuesätzlichi Opfer dargebracht ([[NUM.28.9-NUM.28.10]]); si händ also im Tämpel gschaffet, ohni de Sabbat z bräche. Spööteri rabbinischi Text formuliered de Grundsatz, dass de Tämpeldienscht de Sabbat verdrängt. S Argumänt vo Jesus «Da isch öppis Grössers als de Tämpel» ([[MAT.12.6]]) setzt die Uusnaam voruus. Zum Sabbat allgemein lueg BG-MRK-1006.",
  "Wie wiit di spöötere rabbinische Formulierige d Uuslegig zur Ziit vo Jesus widergänd, isch nöd sicher.",
  ["Schaubroot, Broot vo de Uuslegig", "entweihe"]),
 ("BG-MAT-2020", U(12, 9, 14), "MAT.12.11", READERS, "high", "Ein Tier in der Grube am Sabbat",
  "Ob man einem Tier am Sabbat helfen darf, wurde im Judentum verschieden beantwortet. Die Damaskusschrift, ein Text der Gruppe, zu der auch die Qumran-Gemeinschaft gehörte, verbietet ausdrücklich, einem Tier am Sabbat beim Gebären zu helfen oder es herauszuholen, wenn es in einen Brunnen oder eine Grube gefallen ist. Spätere rabbinische Texte sind milder und erlauben zumindest, das Tier zu versorgen. Jesus setzt in [[MAT.12.11]] voraus, dass seine Zuhörer ein einziges Schaf herausziehen würden; ähnlich argumentiert [[LUK.14.5]].",
  "Welche Auslegung unter den Pharisäern in Galiläa üblich war, ist nicht bekannt; die rabbinischen Texte sind später gesammelt.",
  ["MAT.12.9-MAT.12.14", "LUK.13.15", "LUK.14.5"], ["Damaskusschrift (CD) 11,13–14"],
  [("grc", "βόθυνος", "Grube")],
  "Es Tier i de Gruebe am Sabbat",
  "Öb me eme Tier am Sabbat dörf hälfe, hät me im Judetum verschide beantwortet. D Damaskusschrift, en Text vo de Gruppe, wo au d Qumran-Gmeinschaft dezueghört hät, verbiitet usdrücklich, eme Tier am Sabbat bim Gebäre z hälfe oder s usezhole, wänn s in en Brunne oder in e Gruebe gheit isch. Spööteri rabbinischi Text sind milder und erlaubed zmindescht, s Tier z versorge. De Jesus setzt i [[MAT.12.11]] voruus, dass sini Zuehörer es einzigs Schaf usezieh würded; ähnlich argumentiert [[LUK.14.5]].",
  "Weli Uuslegig under de Pharisäer i Galiläa üeblich gsii isch, weiss me nöd; di rabbinische Text sind spööter gsammlet.",
  ["Gruebe"]),
 ("BG-MAT-2021", U(12, 22, 32), "MAT.12.27", READERS, "probable", "Jüdische Exorzisten",
  "Austreibungen von Dämonen waren nicht auf Jesus beschränkt. Josephus berichtet, er habe gesehen, wie ein Jude namens Eleasar vor Vespasian einen Dämon mit einem Ring und Beschwörungen austrieb, die auf Salomo zurückgeführt wurden. Im Buch Tobit wird ein Dämon durch den Rauch von Fischherz und Leber vertrieben. Mit «euren Söhnen» ([[MAT.12.27]]) meint Jesus Leute aus dem Umfeld seiner Gegner, die ebenfalls austreiben. Nach [[ACT.19.13-ACT.19.14]] versuchten jüdische Beschwörer, im Namen Jesu auszutreiben. Zu Beelzebul und zum Austreiben siehe BG-MRK-0006 und BG-MRK-0007.",
  "Ob «eure Söhne» Schüler der Pharisäer oder allgemein Juden meint, ist offen.",
  ["MAT.12.24-MAT.12.28", "ACT.19.13-ACT.19.14"], ["Josephus, Jüdische Altertümer 8,45–49", "Tobit 8,2–3"],
  [("grc", "ἐκβάλλω", "hinauswerfen, austreiben")],
  "Jüdischi Exorzischte",
  "Uustriibige vo Dämone sind nöd uf de Jesus beschränkt gsii. De Josephus bricht, er heig gseh, wie en Jud mit em Name Eleasar vor em Vespasian en Dämon mit eme Ring und Beschwöörige uustribe heig, wo me uf de Salomo zrugggfüert hät. Im Buech Tobit wird en Dämon dur de Rauch vo Fischhärz und Läbere vertribe. Mit «öine Söö» ([[MAT.12.27]]) meint de Jesus Lüüt us em Umfäld vo sine Gägner, wo au uustriibed. Nach [[ACT.19.13-ACT.19.14]] händ jüdischi Beschwöörer probiert, im Name vo Jesus Dämone uusztriibe. Zu Beelzebul und zum Uustriibe lueg BG-MRK-0006 und BG-MRK-0007.",
  "Öb «öii Söö» Schüeler vo de Pharisäer oder allgemein Jude meint, isch offe.",
  ["usegheie, uustriibe"]),
 ("BG-MAT-2022", U(12, 38, 45), "MAT.12.41-MAT.12.42", READERS, "probable", "Ninive und die Königin des Südens",
  "Ninive war die Hauptstadt Assyriens, des grossen Feindes Israels; nach dem Jonabuch kehrte sie auf Jonas Predigt hin um ([[JON.3.5-JON.3.10]]). Die «Königin des Südens» ist die Königin von Saba, die nach [[1KI.10.1-1KI.10.13]] mit grossem Gefolge kam, um Salomos Weisheit zu prüfen. Saba wird meist im Süden Arabiens gesucht, im heutigen Jemen. Beide stehen für Nichtjuden, die auf Gottes Wort oder Weisheit eingingen. «Beim Gericht aufstehen» ist Rechtssprache: Sie treten als Zeugen auf.",
  "Die Lage von Saba ist nicht sicher; spätere Überlieferung verbindet die Königin auch mit Äthiopien.",
  ["JON.3.5-JON.3.10", "1KI.10.1-1KI.10.13", "2CH.9.1-2CH.9.12", "MAT.12.41-MAT.12.42"], [],
  [("grc", "Νινευίτης", "Bewohner von Ninive"), ("grc", "βασίλισσα νότου", "Königin des Südens")],
  "Ninive und d Königin vom Süde",
  "Ninive isch d Hauptstadt vo Assyrie gsii, vom grosse Find vo Israel; nach em Jonabuech hät si uf d Predig vom Jona hii umgchert ([[JON.3.5-JON.3.10]]). D «Königin vom Süde» isch d Königin vo Saba, wo nach [[1KI.10.1-1KI.10.13]] mit eme grosse Gfolg choo isch, zum d Wiisheit vom Salomo prüefe. Saba sueched me meischtens im Süde vo Arabie, im hütige Jeme. Beidi stönd für Nöd-Jude, wo uf Gottes Wort oder Wiisheit iigange sind. «Bim Gricht ufstaa» isch Grichtsspraach: Si träted als Züüge uf.",
  "D Laag vo Saba isch nöd sicher; spööteri Überliferig verbindet d Königin au mit Äthiopie.",
  ["Bewoner vo Ninive", "Königin vom Süde"]),
 ("BG-MAT-2023", U(13, 1, 9), "MAT.13.3-MAT.13.8", GAL, "possible", "Säen und Ernten in Galiläa",
  "Gesät wurde nach den ersten Herbstregen, meist von Hand aus einem Tuch oder Sack geworfen. Wege führten durch und an den Feldern vorbei, felsiger Untergrund mit dünner Erdschicht und Dornen waren in Galiläa verbreitet. Ob man zuerst säte und dann pflügte, wird diskutiert: Joachim Jeremias schloss das unter anderem aus der Reihenfolge «säen, pflügen» in der Liste der verbotenen Sabbatarbeiten in der Mischna; andere halten das für nicht beweiskräftig. Ein hundertfacher Ertrag gilt in [[GEN.26.12]] als besonderer Segen; gewöhnliche Erträge waren deutlich geringer, die Schätzungen gehen aber weit auseinander.",
  "Die Frage der Reihenfolge von Säen und Pflügen ist offen; die Angaben zu Erträgen in der Antike sind unsicher. Die Textfassungen der Mischna stimmen hier nicht überein: Die gedruckte Ausgabe nennt «säen» vor «pflügen», eine von der JTSA wiedergegebene hebräische Fassung «pflügen» zuerst.",
  ["MAT.13.3-MAT.13.8", "MAT.13.18-MAT.13.23", "GEN.26.12"], ["Mischna, Schabbat 7,2"],
  [("grc", "σπείρω", "säen"), ("grc", "πετρώδης", "felsig, steinig")],
  "Sääe und Ärne in Galiläa",
  "Gsäät hät me nach de erschte Herbschtrege, meischtens vo Hand us eme Tuech oder Sack. Wäg sind dur d Fälder und a ine verbii gfüert, felsige Bode mit ere dünne Ärdschicht und Dörn sind in Galiläa verbreitet gsii. Öb me zerscht gsäät und dänn pflüeget hät, wird diskutiert: De Joachim Jeremias hät das under anderem us de Reihefolg «sääe, pflüege» i de Lischte vo de verbottnige Sabbatarbete i de Mischna gschlosse; anderi halted das für nöd beweiskräftig. En hundertfache Ertrag gilt i [[GEN.26.12]] als bsundere Säge; gwöönlichi Ertrög sind tüütlich chliiner gsii, d Schätzige gönd aber wiit usenand.",
  "D Frag vo de Reihefolg vo Sääe und Pflüege isch offe; d Aagaabe zu Ertrög i de Antike sind unsicher. D Textfassige vo de Mischna stimmed da nöd überii: Di druckt Uusgaab nännt «sääe» vor «pflüege», e hebräischi Fassig, wo d JTSA widergit, «pflüege» zerscht.",
  ["sääe", "felsig, steinig"]),
 ("BG-MAT-2024", U(13, 24, 30), "MAT.13.25", GAL, "probable", "Unkraut im Weizen",
  "Das griechische ζιζάνιον bezeichnet wahrscheinlich den Taumellolch (Lolium temulentum), ein Gras, das jungem Weizen sehr ähnlich sieht und sich erst beim Ährenansatz deutlich unterscheidet ([[MAT.13.26]]). Seine Körner sind oft von einem Pilz befallen und machen, mit dem Getreide vermahlen, Schwindel und Übelkeit. Die Wurzeln von Lolch und Weizen verflechten sich, sodass Ausreissen den Weizen gefährdet ([[MAT.13.29]]). In der Mischna gelten Weizen und «Zunin» als so ähnlich, dass sie nicht als verschiedene Arten gelten. Das Unkraut wurde nach der Ernte aussortiert und konnte als Brennstoff dienen ([[MAT.13.30]]).",
  "Die Gleichsetzung von ζιζάνιον mit dem Taumellolch ist verbreitet, aber nicht völlig sicher; dass «Zunin» dieselbe Pflanze meint, ebenfalls.",
  ["MAT.13.24-MAT.13.30", "MAT.13.36-MAT.13.43"], ["Mischna, Kilajim 1,1"],
  [("grc", "ζιζάνιον", "Unkraut, wohl Taumellolch"), ("heb", "זוּנִין", "Lolch (Unkraut im Getreide)", "zûnîn")],
  "Uchruut im Weize",
  "S griechisch ζιζάνιον bezeichnet wahrschiinli de Taumellolch (Lolium temulentum), es Gras, wo junge Weize sehr gliich gseht und sich erscht bim Äriaasetze tüütlich underscheidet ([[MAT.13.26]]). Sini Chörner sind oft vo me Pilz befalle und mached, mit em Getreid gmaale, Schwindel und Übelkeit. D Wurzle vo Lolch und Weize verflächted sich, so dass s Uusriisse de Weize gfährdet ([[MAT.13.29]]). I de Mischna gälted Weize und «Zunin» als so ähnlich, dass si nöd als verschideni Arte gälted. S Uchruut hät me nach de Ärn uussortiert, und me hät s als Brännstoff chöne bruuche ([[MAT.13.30]]).",
  "D Gliichsetzig vo ζιζάνιον mit em Taumellolch isch verbreitet, aber nöd ganz sicher; dass «Zunin» di gliich Pflanze meint, au nöd.",
  ["Uchruut, wahrschiinli Taumellolch", "Lolch (Uchruut im Getreid)"]),
 ("BG-MAT-2025", U(13, 31, 35), "MAT.13.31-MAT.13.33", GAL, "probable", "Senfkorn und Sauerteig",
  "Gemeint ist wahrscheinlich der Schwarze Senf, eine einjährige Pflanze, die am See Gennesaret über zwei Meter hoch werden kann. Sein Korn war sprichwörtlich klein (vgl. [[MAT.17.20]]). Dass Vögel in den Zweigen nisten, erinnert an das Bild vom Weltenbaum, unter dem die Völker Schutz finden ([[DAN.4.12]]; [[EZK.17.23]]; [[EZK.31.6]]). Sauerteig ist ein Rest gesäuerten Teigs, mit dem man neuen Teig durchsäuert; sonst steht er oft für verderblichen Einfluss ([[EXO.12.15]]; [[MAT.16.6]]; [[1CO.5.6-1CO.5.8]]). Drei Sea (σάτα) Mehl, wie sie Sara für die Gäste Abrahams backte ([[GEN.18.6]]), sind eine sehr grosse Menge, nach gängigen Schätzungen mehrere Dutzend Liter.",
  "Die Bestimmung der Pflanze und die Umrechnung der Sea in heutige Masse sind unsicher.",
  ["MAT.13.31-MAT.13.33", "LUK.13.18-LUK.13.21", "DAN.4.12", "EZK.17.23", "EZK.31.6", "GEN.18.6", "MAT.16.6"], [],
  [("grc", "σίναπι", "Senf"), ("grc", "ζύμη", "Sauerteig"), ("grc", "σάτον", "Sea, ein Hohlmass")],
  "Sänfchorn und Suurteig",
  "Gmeint isch wahrschiinli de Schwarz Sänf, e einjärigi Pflanze, wo am See Gennesaret über zwei Meter hoch cha wärde. Sis Chorn isch sprichwörtlich chlii gsii (vgl. [[MAT.17.20]]). Dass Vögel i de Escht näschted, erinneret as Bild vom Wältebaum, wo d Völker drunder Schutz finded ([[DAN.4.12]]; [[EZK.17.23]]; [[EZK.31.6]]). Suurteig isch en Räscht vo gsüürtem Teig, wo me dämit nöie Teig suur macht; suscht staat er oft für en verderbliche Iifluss ([[EXO.12.15]]; [[MAT.16.6]]; [[1CO.5.6-1CO.5.8]]). Drüü Sea (σάτα) Määl, wie si d Sara für d Gäscht vom Abraham bache hät ([[GEN.18.6]]), sind e sehr grossi Mängi, nach gängige Schätzige es paar Dotzed Liter.",
  "D Bestimmig vo de Pflanze und d Umrächnig vo de Sea i hütigi Mass sind unsicher.",
  ["Sänf", "Suurteig", "Sea, es Hohlmass"]),
 ("BG-MAT-2026", U(13, 53, 58), "MAT.13.55", GAL, "possible", "Der Zimmermann in Nazaret",
  "Das Wort τέκτων bezeichnet einen Handwerker, der mit Holz, oft auch mit Stein baut: Bauhandwerker, Zimmermann, Schreiner. Justin der Märtyrer schreibt im 2. Jahrhundert, Jesus habe als Handwerker Pflüge und Joche gemacht. Nazaret war ein kleines Dorf; etwa sechs Kilometer entfernt baute Herodes Antipas Sepphoris als Hauptstadt neu auf. Ob Josef und Jesus dort Arbeit fanden, ist eine verbreitete, aber unbelegte Vermutung. Zu Jesu Brüdern und Schwestern siehe BG-MRK-0011.",
  "Justins Angabe kann auf Überlieferung oder auf eigener Ausmalung beruhen. Die Arbeit in Sepphoris ist eine Vermutung.",
  ["MAT.13.54-MAT.13.56", "MRK.6.3", "MAT.2.23"], ["Justin, Dialog mit Tryphon 88,8"],
  [("grc", "τέκτων", "Bauhandwerker, Zimmermann")],
  "De Zimmermaa z Nazaret",
  "S Wort τέκτων bezeichnet en Handwärker, wo mit Holz, oft au mit Stei baut: Bauhandwärker, Zimmermaa, Schriiner. De Justin de Märtyrer schriibt im 2. Jaarhundert, de Jesus heig als Handwärker Pflüeg und Joch gmacht. Nazaret isch es chliises Dorf gsii; öppe sächs Kilometer devo hät de Herodes Antipas Sepphoris als Hauptstadt nöi uufbaut. Öb de Josef und de Jesus det Arbet gfunde händ, isch e verbreiteti, aber unbelegti Vermuetig. Zu de Brüeder und Schwöschtere vo Jesus lueg BG-MRK-0011.",
  "Em Justin sini Aagaab cha uf Überliferig oder uf eigeter Uusmaalig berue. D Arbet z Sepphoris isch e Vermuetig.",
  ["Bauhandwärker, Zimmermaa"]),
 ("BG-MAT-2027", U(14, 1, 12), "MAT.14.1", GAL, "high", "Tetrarch, nicht König",
  "Herodes Antipas, ein Sohn Herodes des Grossen, herrschte von 4 v. Chr. bis 39 n. Chr. über Galiläa und Peräa. Sein Titel war «Tetrarch» (ursprünglich «Herrscher über ein Viertel»), in römischer Zeit die Bezeichnung für einen abhängigen Fürsten unterhalb des Königsrangs. Als er sich später um den Königstitel bemühte, wurde er von Kaiser Caligula abgesetzt und nach Gallien verbannt. Dass das Volk ihn dennoch «König» nennen konnte, ist gut denkbar; Matthäus gebraucht beide Bezeichnungen ([[MAT.14.1]]; [[MAT.14.9]]). Zur Familie und zum Tod des Täufers siehe BG-MRK-1009 und BG-MAT-2014.",
  "Wie verbreitet die volkstümliche Anrede «König» für Antipas war, ist nicht belegt. Den Verbannungsort nennt Josephus in den Altertümern Lyon in Gallien (18,252), im Jüdischen Krieg aber Spanien (2,183).",
  ["MAT.14.1-MAT.14.12", "LUK.3.1", "LUK.9.7", "MRK.6.14"], ["Josephus, Jüdische Altertümer 18,240–255"],
  [("grc", "τετραάρχης", "Tetrarch, Vierfürst")],
  "Tetrarch, nöd König",
  "De Herodes Antipas, en Sohn vom Herodes em Groosse, hät vo 4 v. Chr. bis 39 n. Chr. über Galiläa und Peräa gherrscht. Sin Titel isch «Tetrarch» gsii (ursprünglich «Herrscher über es Viertel»), i de römische Ziit d Bezeichnig für en abhängige Fürscht underhalb vom Königsrang. Won er sich spööter um de Königstitel bemüet hät, hät en de Kaiser Caligula abgsetzt und uf Gallie verbannt. Dass s Volk en trotzdem «König» hät chöne nänne, isch guet dänkbar; de Matthäus bruucht beidi Bezeichnige ([[MAT.14.1]]; [[MAT.14.9]]). Zur Familie und zum Tod vom Täufer lueg BG-MRK-1009 und BG-MAT-2014.",
  "Wie verbreitet di volkstümlich Aared «König» für de Antipas gsii isch, isch nöd belegt. De Verbannigsort nännt de Josephus i de Altertümer Lyon in Gallie (18,252), im Jüdische Chrieg aber Spanie (2,183).",
  ["Tetrarch, Vierfürscht"]),
 ("BG-MAT-2028", U(14, 22, 33), "MAT.14.24-MAT.14.25", GAL, "probable", "Stadien und Nachtwachen",
  "Ein Stadion (στάδιον) mass etwa 185 Meter; «viele Stadien» vom Land ([[MAT.14.24]]) heisst also wohl mehrere Kilometer (vgl. [[JHN.6.19]]: 25 oder 30 Stadien). Die Römer teilten die Nacht in vier Wachen; die «vierte Nachtwache» ist die Zeit vor Tagesanbruch, etwa von drei bis sechs Uhr. Auch [[MRK.13.35]] setzt vier Wachen voraus. Ältere biblische Texte kennen drei Nachtwachen ([[JDG.7.19]]; [[LAM.2.19]]). Plötzliche Fallwinde von den umliegenden Höhen sind am See Gennesaret bis heute bekannt.",
  "Die genaue Länge des Stadions schwankte je nach Ort. Ob Matthäus mit «vierte Nachtwache» an die römische Zählung denkt oder nur «gegen Morgen» meint, ist nicht sicher.",
  ["MAT.14.24-MAT.14.25", "MRK.6.48", "JHN.6.19", "MRK.13.35", "JDG.7.19", "LAM.2.19"], [],
  [("grc", "στάδιον", "Stadion, Längenmass von etwa 185 m"), ("grc", "φυλακή", "Wache, Nachtwache")],
  "Stadie und Nachtwache",
  "Es Stadion (στάδιον) hät öppe 185 Meter gmässe; «vili Stadie» vom Land ([[MAT.14.24]]) heisst also wohl es paar Kilometer (vgl. [[JHN.6.19]]: 25 oder 30 Stadie). D Römer händ d Nacht i vier Wache iiteilt; di «viert Nachtwach» isch d Ziit vor em Tagesaabruch, öppe vo drüü bis sächs. Au [[MRK.13.35]] setzt vier Wache voruus. Elteri biblischi Text känned drüü Nachtwache ([[JDG.7.19]]; [[LAM.2.19]]). Plötzlichi Fallwind vo de Höchine rundume sind am See Gennesaret bis hüt bekannt.",
  "Di gnau Längi vom Stadion hät je nach Ort gschwankt. Öb de Matthäus mit «vierti Nachtwach» a d römischi Zellig dänkt oder nu «gäg de Morge» meint, isch nöd sicher.",
  ["Stadion, Längemass vo öppe 185 m", "Wach, Nachtwach"]),
 ("BG-MAT-2029", U(14, 13, 21), "MAT.14.19", READERS, "probable", "Der Segen über dem Brot",
  "Bei einer jüdischen Mahlzeit sprach der Hausvater über dem Brot einen Lobspruch, brach es und verteilte es; nach der Mischna lautet der Segen über Brot: «… der Brot aus der Erde hervorbringt». Der Segen richtet sich an Gott, nicht an das Brot: «sprach den Segen» (εὐλογέω, [[MAT.14.19]]) heisst, Gott zu loben. Der Blick zum Himmel ist eine Gebetsgebärde (vgl. [[JHN.11.41]]; [[JHN.17.1]]). Brot war das Grundnahrungsmittel; Fisch wurde am See gesalzen oder getrocknet aufbewahrt (BG-MRK-1002).",
  "Die Mischna wurde um 200 n. Chr. gesammelt; dass der Wortlaut des Segens schon im 1. Jahrhundert so lautete, ist wahrscheinlich, aber nicht sicher.",
  ["MAT.14.19", "MAT.15.36", "MAT.26.26", "JHN.11.41", "JHN.17.1"], ["Mischna, Berachot 6,1"],
  [("grc", "εὐλογέω", "segnen, lobpreisen"), ("heb", "בְּרָכָה", "Segensspruch, Lobspruch", "bᵉrākā")],
  "De Säge über em Broot",
  "Bi ere jüdische Maalziit hät de Huusvatter über em Broot en Lobspruch gseit, s broche und verteilt; nach de Mischna lautet de Säge über em Broot: «… wo Broot us de Ärde füürebringt». De Säge richtet sich a Gott, nöd as Broot: «hät de Säge gsproche» (εὐλογέω, [[MAT.14.19]]) heisst, Gott lobe. De Blick zum Himel isch e Gebättsgebäärde (vgl. [[JHN.11.41]]; [[JHN.17.1]]). Broot isch s Grundnaarigsmittel gsii; Fisch hät me am See gsalze oder tröchnet uufbewaart (BG-MRK-1002).",
  "D Mischna isch um 200 n. Chr. gsammlet worde; dass de Wortluut vom Säge scho im 1. Jaarhundert eso glautet hät, isch wahrschiinli, aber nöd sicher.",
  ["sägne, lobpriise", "Sägensspruch, Lobspruch"]),
]

